def flatten(values):
    result = []

    def visit(value):
        if isinstance(value, (list, tuple)):
            for child in value:
                visit(child)
        else:
            result.append(value)

    visit(values)
    return result

print(flatten([1, [2, (3, 4)], "go"]))  # [1, 2, 3, 4, 'go']
